function t(k){return (TXT[S.lang]||TXT.en)[k]??TXT.en[k]??k}function L(o){if(o&&typeof o==='object')return o[S.lang]??o.en??o.ta??'';return o??''}const VOICE_LOCALE={ta:"ta-IN",en:"en-IN",hi:"hi-IN",ml:"ml-IN"};function shortSay(x){x=String(x||'');if(x.length<=260)return x;const p=x.slice(0,260).match(/^[\s\S]*[.!?।]/);return p?p[0]:x.slice(0,260)}function voiceSpeak(text,opts){if(typeof window.RaastaVoice?.speak!=='function'){return Promise.resolve()}try{S.isPlayingAudio=true;orbState('speaking');return Promise.resolve(window.RaastaVoice.speak(opts&&opts.full?text:shortSay(text),VOICE_LOCALE[S.lang])).catch(()=>{}).finally(()=>{S.isPlayingAudio=false;orbState('idle')})}catch{S.isPlayingAudio=false;return Promise.resolve()}}
function voiceFallback(){S.isListening=false;S.msgs.push({who:'bot',text:t('tapFallback')});render()}
function voiceListen(){if(S.isListening)return;if(typeof window.RaastaVoice?.listen!=='function'){voiceFallback();return}S.isListening=true;render();orbState('listening');try{Promise.resolve(window.RaastaVoice.listen(VOICE_LOCALE[S.lang])).then(x=>{S.isListening=false;orbState('idle');const text=typeof x==='string'?x:x?.text;if(text)processSpeechInput(text);else{S.msgs.push({who:'bot',text:t('notUnderstood')});render()}}).catch(()=>voiceFallback())}catch{voiceFallback()}}
function askQuestion(){const q=QUESTIONS[S.step];if(!q){S.msgs.push({who:'bot',text:t('done')});render();return}S.msgs.push({who:'bot',text:L(q)});voiceSpeak(L(q));render()}
function answerQuestion(o,heard){const q=QUESTIONS[S.step];if(!q)return;S.msgs.push({who:'me',text:heard||L(o)});S.profile[q.key]=q.key==='interests'?[o.v]:o.v;S.step++;askQuestion()}
