const normSpeech=s=>' '+String(s||'').normalize('NFC').toLowerCase().replace(/[‌‍]/g,'').replace(/[.,!?;:।|"'“”‘’()\[\]\/\₹%–—-]+/g,' ').replace(/\s+/g,' ').trim()+' ';
const SPOKEN={stitching:['தையல்','துணி','തയ്യ','തുന്ന','सिलाई','सिल','कपड़े सिल'],phone_repair:['மொபைல்','ഫോൺ','മൊബൈൽ','फोन','फ़ोन','मोबाइल'],drawing:['ஓவியம்','வரை','ചിത്ര','വരയ്ക്ക','വര','चित्र','ड्रॉइंग','पेंटिंग'],computers:['கம்ப்யூட்டர்','കമ്പ്യൂട്ട','कंप्यूटर','कम्प्यूटर'],farming:['விவசாய','கிருஷி','കൃഷി','കൃഷ','खेती','खेत'],cooking:['சமையல்','சமை','പാചക','ഭക്ഷണം ഉണ്ടാക്ക','खाना बना','खाना','पकाना'],female:['பெண்','പെൺ','ലഡ','लड़की','लडकी'],male:['ஆண்','ആൺ','लड़का','लडका'],true:['ஆம்','ஆமா','ஆமாம்','அரசு','അതെ','ഉവ്വ്','സർക്കാർ','हाँ','हां','सरकारी'],false:['இல்லை','தனியார்','ഇല്ല','പ്രൈവറ്റ്','नहीं','प्राइवेट'],ug:['கல்லூரி','കോളേജ്','कॉलेज','डिग्री'],dropout:['நிறுத்த','നിർത്ത','छोड़']};
const NUMWORDS={15:['fifteen','பதினைந்து','पंद्रह','പതിനഞ്ച'],16:['sixteen','பதினாறு','सोलह','പതിനാറ'],17:['seventeen','பதினேழு','सत्रह','പതിനേഴ'],18:['eighteen','பதினெட்டு','अठारह','പതിനെട്ട'],19:['nineteen','பத்தொன்பது','उन्नीस','പത്തൊമ്പത'],20:['twenty','இருபது','बीस','ഇരുപത'],21:['twenty one','இருபத்தி ஒன்று','इक्कीस','ഇരുപത്തിയൊന്ന']};
const DONT_KNOW=['dont know','don t know','do not know','not sure','no idea','nothing','தெரியாது','தெரியல','தெரியவில்லை','ஒன்றும்','ஒண்ணும்','पता नहीं','नहीं पता','मालूम नहीं','कुछ नहीं','नहीं जानत','അറിയില്ല','അറിഞ്ഞൂട','അറിയത്തില്ല','ഒന്നും','ഉറപ്പില്ല'];
const hasWordStem=(u,w)=>{w=normSpeech(w).trim();if(!w)return false;if(/^[a-z0-9 ]+$/.test(w))return w.length<4?u.includes(' '+w+' '):u.includes(' '+w);if(u.includes(w))return true;const stem=[...w].slice(0,-1).join('');return [...stem].length>=3&&u.includes(' '+stem)};
function matchOption(q,heard){const u=normSpeech(heard);if(q.key==='age'){const d=(u.match(/\d{2}/)||[])[0];let n=d?+d:null;if(n==null)for(const [k,ws] of Object.entries(NUMWORDS))if(ws.some(w=>hasWordStem(u,w)))n=+k;if(n!=null){const o=q.options.find(x=>x.v===Math.min(21,n));if(o)return o}}
 const labelsOf=o=>['en','ta','hi','ml'].map(l=>o[l]).filter(Boolean);const wordCount={};q.options.forEach(o=>new Set(labelsOf(o).flatMap(l=>normSpeech(l).trim().split(' '))).forEach(w=>wordCount[w]=(wordCount[w]||0)+1));
 const scored=q.options.map(o=>{let sc=0;for(const l of labelsOf(o)){const n=normSpeech(l);if(u.includes(n))sc=Math.max(sc,6);else if(n.trim().split(' ').length===1&&hasWordStem(u,n))sc=Math.max(sc,5);for(const w of n.trim().split(' '))if(wordCount[w]===1&&[...w].length>=3&&!/^\d+$/.test(w)&&hasWordStem(u,w))sc=Math.max(sc,3)}for(const k of [...(o.kw||[]),...(SPOKEN[String(o.v)]||[])])if(hasWordStem(u,k))sc=Math.max(sc,4);return {o,sc}}).sort((a,b)=>b.sc-a.sc);
 if(!scored[0].sc||(scored[1]&&scored[1].sc===scored[0].sc))return null;return scored[0].o}
const saysDontKnow=heard=>{const u=normSpeech(heard);return DONT_KNOW.some(p=>u.includes(normSpeech(p).trim()))};
function answerUnsure(heard){const q=QUESTIONS[S.step];if(!q)return;S.msgs.push({who:'me',text:heard||t('notSure')});if(q.key==='interests')S.profile.interests=[];else delete S.profile[q.key];S.msgs.push({who:'bot',text:t(q.key==='interests'?'unsureInterest':'unsureSkip')});S.step++;askQuestion()}
async function aiUnderstand(q,text){if(!navigator.onLine)return null;try{const ctl=new AbortController();const to=setTimeout(()=>ctl.abort(),9000);const r=await fetch('api/understand',{method:'POST',headers:{'Content-Type':'application/json'},signal:ctl.signal,body:JSON.stringify({lang:VOICE_LOCALE[S.lang],question:L(q),answer:text,options:q.options.map(o=>({v:o.v,label:L(o)}))})});clearTimeout(to);return r.ok?await r.json():null}catch{return null}}
async function processSpeechInput(text){if(S.chatMode==='ai'){aiChatTurn(text);return}const q=QUESTIONS[S.step];if(!q)return;const o=matchOption(q,text);if(o&&!saysDontKnow(text)){answerQuestion(o,text);return}if(q.key==='interests'&&!saysDontKnow(text)){const tg=skillTags([text]);if(tg.length){S.msgs.push({who:'me',text});S.profile.interests=tg;S.skills=S.skills||[];if(!S.skills.includes(text))S.skills.push(text);S.step++;askQuestion();return}}
 // Keywords couldn't place it: ask the AI to understand the answer (falls back to the simple rules offline).
 const stepAt=S.step;S.msgs.push({who:'me',text},{who:'bot',text:'…',thinking:true});render();const ai=await aiUnderstand(q,text);const i=S.msgs.findIndex(m=>m.thinking);if(i>=0)S.msgs.splice(i,1);if(S.step!==stepAt)return;S.msgs.pop();
 if(ai&&ai.value!==null&&ai.value!==undefined){const opt=q.options.find(x=>JSON.stringify(x.v)===JSON.stringify(ai.value));if(opt){S.msgs.push({who:'me',text});if(ai.reply)S.msgs.push({who:'bot',text:ai.reply});answerQuestionQuiet(opt);return}}
 if((ai&&ai.unsure)||(!ai&&saysDontKnow(text))){answerUnsure(text);return}
 const r=(ai&&ai.reply)||t('notUnderstood');S.msgs.push({who:'me',text},{who:'bot',text:r});render();if(ai&&ai.reply)voiceSpeak(r)}
function answerQuestionQuiet(o){const q=QUESTIONS[S.step];if(!q)return;S.profile[q.key]=q.key==='interests'?[o.v]:o.v;S.step++;askQuestion()}
const complete=()=>S.step>=QUESTIONS.length||!!S.aiDone;function loadKavya(){S.profile={...KAVYA};S.msgs=[{who:'me',text:t('ownStitch')},{who:'bot',text:t('routeReady')}];S.step=QUESTIONS.length;S.view='careers';render()}
function topbar(title,eyebrow,desc=''){return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`}function paths(){const ai=S.aiRoutes||[];const hasInt=(S.profile.interests||[]).length;const noSew=c=>!c.tags.includes('stitching')||(S.profile.interests||[]).includes('stitching');const m0=hasInt?matchCareers(S.profile):matchCareers(S.profile).filter(noSew);const m=ai.length?[...ai,...((S.profile.interests||[]).length?m0:[])].slice(0,5):m0;return m.length?m:matchCareers({...S.profile,education:undefined}).filter(noSew).concat(CAREERS.filter(c=>c.type==='vocational'&&(!c.tags.includes('stitching')||(S.profile.interests||[]).includes('stitching')))).filter((c,i,a)=>a.findIndex(x=>x.id===c.id)===i).slice(0,4)}
function picker(){return `<section class="welcome"><div class="atlas-mark" aria-hidden="true"><svg viewBox="0 0 120 120"><path d="M12 92C42 92 34 36 68 36s18 48 42 48" fill="none" stroke="#176f50" stroke-width="5" stroke-linecap="round" stroke-dasharray="2 10"/><circle cx="12" cy="92" r="8" fill="#c78b3e"/><circle cx="68" cy="36" r="8" fill="#176f50"/><path d="M94 82l16 2-10 13z" fill="#176f50"/></svg></div><div class="eyebrow">RAASTA · ராஸ்தா</div><h1>${t('welcomeTitle')}</h1><p>${t('welcomeBody')}</p><div class="eyebrow choose-label">${t('choose')}</div><div class="language-options">${LANGS.map(([id,label])=>`<button class="language-option ${S.lang===id?'selected':''}" lang="${id}" aria-pressed="${S.lang===id}" data-act="lang" data-v="${id}"><span>${label}</span><span class="language-check" aria-hidden="true">${S.lang===id?'✓':''}</span></button>`).join('')}</div><button class="primary-action" data-act="continue">${t('continue')} <span aria-hidden="true">→</span></button></section>`}
function welcome(){return `<section class="welcome"><div class="atlas-mark" aria-hidden="true"><svg viewBox="0 0 120 120"><path d="M12 92C42 92 34 36 68 36s18 48 42 48" fill="none" stroke="#176f50" stroke-width="5" stroke-linecap="round" stroke-dasharray="2 10"/><circle cx="12" cy="92" r="8" fill="#c78b3e"/><circle cx="68" cy="36" r="8" fill="#176f50"/><path d="M94 82l16 2-10 13z" fill="#176f50"/></svg></div><div class="eyebrow">RAASTA · ராஸ்தா</div><h1>${t("welcomeTitle")}</h1><p>${t("welcomeBody")}</p><button class="primary-action" data-act="start-chat">${t("talkTitle")} →</button>${(window.RaastaAuth&&RaastaAuth.me()&&!RaastaAuth.me().demo)?'':`<button class="quiet-action" data-act="kavya">${t("startDemo")}</button>`}</section>`}
function routes(){return `<section class="atlas-intro"><div class="eyebrow">${t('possible')}</div><h1>${t('routes')}</h1><p>${t('routeIntro')}</p><div class="route-map"><svg viewBox="0 0 340 92" aria-hidden="true"><path d="M14 68 C90 68 77 22 150 22 S220 72 326 30" fill="none" stroke="#9db7a5" stroke-width="3" stroke-dasharray="5 7"/><circle cx="18" cy="68" r="7" fill="#d69742"/><circle cx="150" cy="22" r="7" fill="#177755"/><circle cx="326" cy="30" r="7" fill="#177755"/></svg><div class="map-labels"><span>${t('today')}</span><span>${t('learn')}</span><span>${t('next')}</span></div></div></section>${S.aiRoutesLoading?`<article class="route-item"><div class="route-content"><p>${t('aiRoutesLoading')}</p></div></article>`:''}${paths().map((c,i)=>`<article class="route-item"><div class="route-index">0${i+1}</div><div class="route-content">${routeArt(c)}<div class="route-type">${esc(typeLabel(c.type))}</div><h2>${esc(L(c.title))}</h2><p>${esc(c.why_i18n?.[S.lang]??c.why)}</p><div class="route-meta">${c.ai?t('aiRoute'):''}</div>${jobSee(c)}<button class="text-action" data-act="career" data-v="${esc(c.id)}">${t('explore')} <span aria-hidden="true">→</span></button></div></article>`).join('')}`}
// "What does this job look like?" A real photo (Wikipedia, no key needed) plus Google Images and YouTube links.
const SEE_TXT={en:['See people doing this','Watch a day at work','Photo: Wikimedia Commons'],ta:['இந்த வேலை செய்பவர்களைப் பாருங்கள்','ஒரு வேலை நாளைப் பாருங்கள்','படம்: விக்கிமீடியா'],hi:['यह काम करने वालों को देखें','काम का एक दिन देखें','फ़ोटो: विकिमीडिया'],ml:['ഈ ജോലി ചെയ്യുന്നവരെ കാണൂ','ഒരു ജോലി ദിവസം കാണൂ','ചിത്രം: വിക്കിമീഡിയ']};
const JOB_OF={fashion_tech:'fashion designer',garment_supervisor:'garment factory',iti_sewing:'tailor',textile_design_digital:'textile designer',mobile_tech:'mobile phone repair',agri_drone:'agricultural drone',food_processing:'food processing',teacher:'teacher'};function jobName(c){return String(c.job||JOB_OF[c.id]||(c.title&&c.title.en)||L(c.title)||'').replace(/\(.*?\)/g,'').trim()}
function jobSee(c){const j=jobName(c);if(!j)return '';const st=SEE_TXT[S.lang]||SEE_TXT.en;const q=encodeURIComponent(j+' India');setTimeout(loadJobPics,0);return `<div class="job-see" data-job="${esc(j)}"><figure hidden style="margin:10px 0 6px"><img alt="${esc(j)}" loading="lazy" style="width:100%;max-height:180px;object-fit:cover;border-radius:12px;display:block"><figcaption style="font-size:11px;opacity:.6;margin-top:4px">${st[2]}</figcaption></figure><div style="display:flex;flex-wrap:wrap;gap:8px;margin:8px 0"><a class="text-action" target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${q}">📷 ${st[0]}</a><a class="text-action" target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(j+' day in the life India')}">▶ ${st[1]}</a></div></div>`}
const JOB_PIC={};try{Object.assign(JOB_PIC,JSON.parse(localStorage.getItem('raasta_jobpics3')||'{}'))}catch{}
function loadJobPics(){document.querySelectorAll('.job-see[data-job]:not([data-done])').forEach(el=>{el.dataset.done='1';const j=el.dataset.job;const show=u=>{if(!u)return;const f=el.querySelector('figure');f.querySelector('img').src=u;f.hidden=false};if(j in JOB_PIC)return show(JOB_PIC[j]);if(!navigator.onLine)return;fetch('https://commons.wikimedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrnamespace=6&gsrlimit=6&gsrsearch='+encodeURIComponent(j+' India filetype:bitmap')+'&prop=imageinfo&iiprop=url&iiurlwidth=480').then(r=>r.json()).then(d=>{const words=j.toLowerCase().split(/\s+/).filter(w=>w.length>3);const pages=d.query?Object.values(d.query.pages).sort((a,b)=>a.index-b.index):[];const p=pages.find(p=>{const tt=p.title.toLowerCase();return words.length&&words.every(w=>tt.includes(w.replace(/s$/,'')))});const u=p&&p.imageinfo&&p.imageinfo[0]&&p.imageinfo[0].thumburl||'';JOB_PIC[j]=u;try{localStorage.setItem('raasta_jobpics3',JSON.stringify(JOB_PIC))}catch{}show(u)}).catch(()=>{})})}
// Free-text skills from the conversation -> catalogue tags, so matching also works offline and for unexpected skills.
