function pathway(){const c=[...(S.aiRoutes||[]),...CAREERS].find(x=>x.id===S.careerId)||paths()[0]||CAREERS[0];return `${topbar(esc(L(c.title)),t('myPath'),esc(c.why_i18n?.[S.lang]??c.why))}${jobSee(c)}<section class="parent-note"><div class="eyebrow">${t('parent')}</div><p>${t('parentBody')}</p><button class="secondary-action" data-act="go" data-v="parent">${PT().open} →</button></section><section class="path-section"><div class="section-kicker">${t('weeks')}</div><div class="timeline">${c.path.map((p,i)=>`<div class="timeline-stop"><div class="stop-week">${t('week')} ${i*2+1}–${i*2+2}</div><h2>${esc((typeof STEP_I18N!=='undefined'&&STEP_I18N[p[0]]&&STEP_I18N[p[0]][S.lang])||p[0])}</h2>${p[2]?`<a href="${esc(p[2])}" target="_blank" rel="noopener">${esc(p[1])} ↗</a>`:`<span>${esc(p[1])}</span>`}</div>`).join('')}</div></section><section class="path-section"><div class="section-kicker">${t('admissions')}</div><p>${c.exams.map(esc).join(' · ')}</p></section><button class="secondary-action" data-act="go" data-v="radar">${t('radar')} →</button>`}
function profile(){const P=S.profile||{};const opt=k=>{const q=QUESTIONS.find(x=>x.key===k);const o=q&&q.options.find(x=>x.v===P[k]);return o?L(o):(P[k]!==undefined&&P[k]!==null?String(P[k]):'—')};const ints=(P.interests||[]).map(v=>{const o=QUESTIONS[0].options.find(x=>x.v===v);return o?L(o):v});const rows=[[t('age'),P.age??'—'],[t('class'),opt('education')],[t('school'),opt('govt_school')],[t('income'),opt('family_income_lakh')],[t('community'),opt('category')],[t('marks'),P.marks_percent!=null?P.marks_percent+'%':'—'],[t('skill'),[...ints,...(S.skills||[])].join(', ')||'—']];const me=window.RaastaAuth&&RaastaAuth.me();const nm=(me&&me.name)||P.name||'';const empty=!rows.some(([,v])=>v!=='—'&&v!=='');const E={en:['Nothing here yet','Talk to Raasta for two minutes and your answers will show up here.'],ta:['இன்னும் எதுவும் இல்லை','ராஸ்தாவுடன் இரண்டு நிமிடம் பேசுங்கள். உங்கள் பதில்கள் இங்கே தெரியும்.'],hi:['अभी कुछ नहीं है','रास्ता से दो मिनट बात करें, आपके जवाब यहाँ दिखेंगे।'],ml:['ഇവിടെ ഇതുവരെ ഒന്നുമില്ല','റാസ്തയോട് രണ്ട് മിനിറ്റ് സംസാരിക്കൂ, നിങ്ങളുടെ ഉത്തരങ്ങൾ ഇവിടെ കാണാം.']}[S.lang]||[];if(empty)return `${topbar(nm?esc(nm):t('profile'),t('profile')+' · '+t('genome'),E[1])}<button class="primary-action" data-act="start-chat">${t('talkTitle')} →</button>`;return `${topbar(nm?esc(nm):t('profile'),t('profile')+' · '+t('genome'))}<dl class="profile-list">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><button class="primary-action" data-act="go" data-v="careers">${t('myPath')} →</button>`}
