// Adaptive conversation (online): the AI follows what the student actually says and fills the profile as it learns.
// Offline or on AI failure it continues as the tap-through questionnaire from the first unanswered question.
function startChat(){S.asked=[];S.retried=[];S.lastAsking=null;S.msgs=[];S.step=0;S.aiDone=false;S.skills=[];S.sugg=[];S.convo=[];S.profile={state:'TN',disability:false};S.chatMode=navigator.onLine?'ai':'rules';navigateTo('talk');if(S.chatMode==='ai'){const open=L(QUESTIONS[0]);S.msgs.push({who:'bot',text:open});S.convo.push({role:'assistant',content:open});render();voiceSpeak(open)}else askQuestion()}
function toRules(){S.chatMode='rules';S.step=QUESTIONS.findIndex(q=>S.profile[q.key]===undefined);if(S.step<0)S.step=QUESTIONS.length;askQuestion()}
function finishAI(){S.aiDone=true;S.step=QUESTIONS.length;navigateTo('careers')}
const FALLBACK_TXT={en:'The network is slow, so let’s continue by tapping answers. Nothing you said is lost.',ta:'இணையம் மெதுவாக உள்ளது, பதில்களைத் தொட்டுத் தொடருவோம். நீங்கள் சொன்னது எதுவும் இழக்கப்படவில்லை.',hi:'नेटवर्क धीमा है, इसलिए जवाब छूकर आगे बढ़ते हैं। आपकी कही कोई बात खोई नहीं है।',ml:'നെറ്റ്‌വർക്ക് മന്ദഗതിയിലാണ്, ഉത്തരങ്ങൾ തൊട്ട് തുടരാം. നിങ്ങൾ പറഞ്ഞതൊന്നും നഷ്ടപ്പെട്ടിട്ടില്ല.'};
async function aiChatTurn(text){text=String(text||'').trim();if(!text||S.aiBusy)return;S.aiBusy=true;S.sugg=[];S.msgs.push({who:'me',text},{who:'bot',text:'…',thinking:true});S.convo.push({role:'user',content:text});render();orbState('thinking');let r=null;
 for(let tries=0;tries<2&&!r;tries++){try{const ctl=new AbortController();const to=setTimeout(()=>ctl.abort(),15000);const res=await fetch('api/chat',{method:'POST',headers:{'Content-Type':'application/json'},signal:ctl.signal,body:JSON.stringify({lang:VOICE_LOCALE[S.lang],history:S.convo,profile:S.profile,skills:S.skills,asked:S.asked||[],retried:S.retried||[],lastAsking:S.lastAsking||null})});clearTimeout(to);r=res.ok?await res.json():null}catch{r=null}}
 S.aiBusy=false;S.msgs=S.msgs.filter(m=>!m.thinking);orbState('idle');
 if(!r){S.msgs.push({who:'bot',text:(FALLBACK_TXT[S.lang]||FALLBACK_TXT.en)});toRules();return}
 const u=r.updates||{};const st=skillTags(r.skills||[]);if(st.length)u.interests=[...(u.interests||[]),...st];if(u.interests)u.interests=[...new Set([...(S.profile.interests||[]),...u.interests])];Object.assign(S.profile,u);
 for(const k of r.skills||[])if(!S.skills.some(x=>x.toLowerCase()===k.toLowerCase()))S.skills.push(k);
 S.asked=S.asked||[];S.retried=S.retried||[];if(r.asking){if(r.retry){if(!S.retried.includes(r.asking))S.retried.push(r.asking)}else if(!S.asked.includes(r.asking))S.asked.push(r.asking)}if(r.declined&&!S.asked.includes(r.declined))S.asked.push(r.declined);S.lastAsking=r.asking||null;S.sugg=r.suggestions||[];S.msgs.push({who:'bot',text:r.reply});S.convo.push({role:'assistant',content:r.reply});if(r.done||S.convo.filter(m=>m.role==='user').length>=12){S.aiDone=true;S.step=QUESTIONS.length}render();voiceSpeak(r.reply)}
const DONE_TXT={en:['Your roadmap is ready','Raasta has learned enough about you. Your career routes and step-by-step plan are waiting.','Start a new conversation'],ta:['உங்கள் வழிகாட்டி தயார்','ராஸ்தா உங்களைப் பற்றி போதுமான அளவு தெரிந்துகொண்டது. உங்கள் தொழில் வழிகளும் படிப்படியான திட்டமும் தயார்.','புதிய உரையாடலைத் தொடங்கு'],hi:['आपका रोडमैप तैयार है','रास्ता ने आपके बारे में काफ़ी जान लिया है। आपके करियर रास्ते और कदम-दर-कदम योजना तैयार हैं।','नई बातचीत शुरू करें'],ml:['നിങ്ങളുടെ റോഡ്മാപ്പ് തയ്യാർ','റാസ്ത നിങ്ങളെക്കുറിച്ച് വേണ്ടത്ര മനസ്സിലാക്കി. നിങ്ങളുടെ കരിയർ വഴികളും ഘട്ടംഘട്ടമായ പദ്ധതിയും തയ്യാർ.','പുതിയ സംഭാഷണം തുടങ്ങൂ']};
function talkAI(){S.skills=S.skills||[];S.sugg=S.sugg||[];S.convo=S.convo||[];S.msgs=S.msgs||[];const userTurns=S.convo.filter(m=>m.role==='user').length;return `<div class="orb-stage"><div class="orb-glass"><div class="orb-mount" id="orbMountEl"></div></div></div>${S.skills.length?`<section class="genome" aria-label="${t('genome')}"><div class="eyebrow">${t('genome')}</div><div class="genome-chips">${S.skills.map(k=>`<span class="genome-chip">${esc(k)}</span>`).join('')}</div></section>`:''}<div class="chat-stream" aria-live="polite" aria-relevant="additions text">${S.msgs.map(m=>`<div class="message ${m.who}${m.thinking?' thinking':''}">${esc(m.text)}${m.who==='bot'&&!m.thinking?`<button class="listen-link" data-act="read" data-t="${esc(m.text)}">${t('listen')}</button>`:''}</div>`).join('')}</div>${S.sugg.length?`<div class="sugg-row">${S.sugg.map(x=>`<button class="sugg-chip" data-act="sugg" data-t="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:''}${S.aiDone?`<section class="parent-note" style="text-align:center"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#176f50" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="display:block;margin:0 auto"><path d="M4 20C8 20 7 5 13 5s3 14 7 14"/><circle cx="4" cy="20" r="1.4" fill="#176f50"/><circle cx="20" cy="19" r="1.4" fill="#176f50"/></svg><h2 style="margin:6px 0">${(DONE_TXT[S.lang]||DONE_TXT.en)[0]}</h2><p>${(DONE_TXT[S.lang]||DONE_TXT.en)[1]}</p><button class="primary-action" data-act="ai-finish">${t('seeRoutes')} →</button><button class="text-action" data-act="start-chat" style="margin-top:8px">${(DONE_TXT[S.lang]||DONE_TXT.en)[2]}</button></section>`:`<button class="mic-action mic-hero ${S.isListening?'is-listening':''}" data-act="mic" aria-pressed="${!!S.isListening}" ${S.aiBusy?'disabled':''}><span class="mic-glyph" aria-hidden="true"><svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3zM5 11a7 7 0 0 0 14 0M12 18v3"/></svg></span><span>${S.isListening?t('listening'):t('tapMic')}</span></button><form class="ai-form" id="aiForm"><input id="aiInput" type="text" autocomplete="off" placeholder="${t('typeHere')}" aria-label="${t('typeHere')}" ${S.aiBusy?'disabled':''}><button class="primary-action" type="submit">${t('send')}</button></form>${userTurns>=4?`<button class="secondary-action" data-act="ai-finish">${t('seeRoutes')} →</button>`:''}`}`}
document.addEventListener('submit',e=>{if(e.target.id!=='aiForm')return;e.preventDefault();const i=document.getElementById('aiInput');const v=i.value;i.value='';aiChatTurn(v)});
// Pre-recorded 1.5-minute Parent Mode note for the Kavya demo (made once with Sarvam, so playing it costs no credits).
const KAVYA_NOTE_TA=`வணக்கம் அம்மா, அப்பா. இது ராஸ்தாவிலிருந்து, உங்கள் மகள் காவ்யாவைப் பற்றிய ஒரு சிறிய குரல் செய்தி. காவ்யாவுக்கு பதினேழு வயது. அவள் அரசு பள்ளியில் பன்னிரண்டாம் வகுப்பு படிக்கிறாள். அக்கம்பக்கத்தினருக்கு அவள் துணி தைத்துக் கொடுக்கிறாள் என்பது உங்களுக்குத் தெரியும். அது ஒரு சாதாரண வேலை இல்லை. அளவு எடுப்பது, வெட்டுவது, சரியாகத் தைப்பது, வாடிக்கையாளரிடம் பேசுவது. இவை எல்லாம் உண்மையான தொழில் திறமைகள். இந்தத் திறமையிலிருந்து அவளுக்குப் பல பாதைகள் இருக்கின்றன. ஒன்று, அருகிலுள்ள அரசு ஐடிஐயில் தையல் தொழில்நுட்பம் படிப்பது. இது சுமார் ஒரு வருடப் படிப்பு, சான்றிதழுடன் வேலை தேட உதவும். இரண்டு, ஃபேஷன் டெக்னாலஜியில் டிப்ளோமா அல்லது பட்டப்படிப்பு. மூன்று, அனுபவம் கிடைத்த பிறகு ஆடைத் தொழிற்சாலையில் மேற்பார்வையாளர் வேலை. படிப்புச் செலவைப் பற்றி நீங்கள் கவலைப்படலாம். அரசு பள்ளியில் படித்த மாணவிகள் உயர்கல்வியில் சேரும்போது, புதுமைப் பெண் திட்டம் போன்ற உதவிகள் இருக்கின்றன. காவ்யாவின் குடும்ப வருமானம் மற்றும் பிரிவைப் பொறுத்து வேறு உதவித்தொகைகளும் இருக்கலாம். ஆனால் ஒரு முக்கியமான விஷயம். இவை எதுவும் உறுதி இல்லை. விண்ணப்பிக்கும் முன், அதிகாரப்பூர்வ அரசு இணையதளத்திலோ, பள்ளி ஆசிரியரிடமோ சரிபார்க்க வேண்டும். யாராவது பணம் கேட்டால் கொடுக்க வேண்டாம். நீங்கள் செய்யக்கூடியது இதுதான். ஒரு நாள் காவ்யாவுடன் அமர்ந்து, அவள் எந்தப் பாதையை விரும்புகிறாள் என்று கேளுங்கள். அவளுடைய ஆசிரியரைச் சந்தித்துப் பேசுங்கள். அவள் திறமையை நம்புங்கள். உங்கள் ஆதரவுதான் அவளுடைய முதல் படி. நன்றி.`;
