// Routes from the Skill Genome: asked once per set of skills + language, so it costs one small AI call.
async function loadAIRoutes(){const sk=S.skills||[];if(!sk.length||!navigator.onLine)return;const sig=S.lang+'|'+sk.join('|');if(S.aiRoutesSig===sig)return;S.aiRoutesSig=sig;S.aiRoutesLoading=true;setTimeout(render,0);
 for(let i=0;i<2;i++){try{const r=await fetch('api/routes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:VOICE_LOCALE[S.lang],skills:sk,profile:S.profile})});if(r.ok){S.aiRoutes=(await r.json()).routes||[];break}}catch{}}
 S.aiRoutesLoading=false;if(S.view==='careers')render()}
const views={language:picker,start:welcome,talk:()=>{ensureTalk();return S.chatMode==='ai'?talkAI():talk()},careers:()=>{loadAIRoutes();return routes()},radar,pathway,parent:parentView,profile,facilitator};
function render(){document.documentElement.lang=S.lang;document.documentElement.dataset.lang=S.lang;const bs=document.getElementById('breakoutSlot');if(bs)bs.innerHTML='';const root=$('#viewContainer');root.innerHTML=(views[S.view]||picker)();const hasProfile=complete();$('#appNavbar').style.display=(S.view==='start'||S.view==='language')?'none':'grid';$('#profileHeaderBtn').style.display=hasProfile?'inline-flex':'none';document.querySelectorAll('.app-navbar [data-v]').forEach(b=>{b.classList.toggle('active',b.dataset.v===S.view);b.disabled=false;b.classList.toggle('locked',!canBrowse()&&!['talk','facilitator'].includes(b.dataset.v))});navHistory();backButton();navLabels();const ind=$('#netIndicator'),lab=$('#netLabel');if(ind&&lab){ind.classList.toggle('offline',!navigator.onLine);lab.textContent=navigator.onLine?t('online'):t('offline')}const sw=$('#headerLanguage');if(sw){sw.setAttribute('aria-label',t('choose'));sw.textContent=S.lang.toUpperCase()}if(S.view==='talk'&&S.chatMode==='ai')requestAnimationFrame(mountOrbIfNeeded);else if(window.VoiceOrb)window.VoiceOrb.destroy();updateEditorialPanel();requestAnimationFrame(()=>updateNavIndicator(S.view))}
function setLanguage(lang){if(!LANGS.some(([k])=>k===lang))return;S.lang=lang;try{localStorage.setItem('raasta_lang',lang)}catch{}if(S.view==='language'){S.view=S.pickerReturn==='start'?'language':S.pickerReturn}else if(S.view==='start')S.view='language';render()}
const NAV_TXT={en:['Back','Talk to Raasta first, then your routes will open here.'],ta:['பின்','முதலில் ராஸ்தாவுடன் பேசுங்கள், பிறகு உங்கள் வழிகள் இங்கே திறக்கும்.'],hi:['वापस','पहले रास्ता से बात करें, फिर आपके रास्ते यहाँ खुलेंगे।'],ml:['തിരികെ','ആദ്യം റാസ്തയോട് സംസാരിക്കൂ, പിന്നെ നിങ്ങളുടെ വഴികൾ ഇവിടെ തുറക്കും.']};
const navT=i=>(NAV_TXT[S.lang]||NAV_TXT.en)[i];
const NAV_LABELS={en:{talk:'Talk',careers:'Routes',radar:'Radar',pathway:'Path',parent:'Parent',facilitator:'School'},ta:{talk:'பேசு',careers:'வழிகள்',radar:'ரேடார்',pathway:'பாதை',parent:'பெற்றோர்',facilitator:'பள்ளி'},hi:{talk:'बात',careers:'रास्ते',radar:'रडार',pathway:'राह',parent:'अभिभावक',facilitator:'स्कूल'},ml:{talk:'സംസാരം',careers:'വഴികൾ',radar:'റഡാർ',pathway:'പാത',parent:'രക്ഷിതാവ്',facilitator:'സ്കൂൾ'}};
function navLabels(){const m=NAV_LABELS[S.lang]||NAV_LABELS.en;document.querySelectorAll('.app-navbar [data-v]').forEach(b=>{const sp=b.querySelector('span');if(sp&&m[b.dataset.v])sp.textContent=m[b.dataset.v]})}
function canBrowse(){return complete()||(S.skills||[]).length>0||(S.aiRoutes||[]).length>0||(S.profile&&(S.profile.interests||[]).length>0)}
let navDepth=0,fromPop=false,lastView=null;
function navHistory(){if(S.view===lastView)return;if(fromPop||lastView===null){try{history.replaceState({v:S.view,d:navDepth},'')}catch{}}else{navDepth++;try{history.pushState({v:S.view,d:navDepth},'')}catch{}}lastView=S.view;fromPop=false}
window.addEventListener('popstate',e=>{const v=e.state&&e.state.v;if(!v||!views[v]){return}if(v==='login'&&window.RaastaAuth&&RaastaAuth.me()){try{history.pushState({v:S.view,d:++navDepth},'')}catch{}return}navDepth=e.state.d||0;fromPop=true;try{window.RaastaVoice&&RaastaVoice.stop()}catch{}S.view=v;render();const c=$('#viewContainer');if(c)c.scrollTop=0});
const BACK_TO={pathway:'careers',profile:null,radar:'careers'};
function goBack(){if(navDepth>0){history.back();return}navigateTo(BACK_TO[S.view]||(complete()?'careers':'start'))}
function backButton(){const root=$('#viewContainer');if(!root)return;const show=['pathway','profile','radar'].includes(S.view)||(S.view==='language'&&S.pickerReturn&&S.pickerReturn!=='start');if(!show)return;const b=document.createElement('button');b.type='button';b.className='nav-back';b.setAttribute('data-act','back');b.innerHTML='<span aria-hidden="true">←</span> '+navT(0);b.style.cssText='width:auto;align-self:flex-start;flex:0 0 auto;display:inline-flex;align-items:center;gap:6px;margin:4px 0 6px;padding:8px 14px 8px 10px;border-radius:999px;border:1px solid var(--line,#d7ddd4);background:transparent;color:inherit;font:600 14px Inter,sans-serif;cursor:pointer';root.prepend(b)}
function navToast(msg){let el=document.getElementById('navToast');if(!el){el=document.createElement('div');el.id='navToast';el.setAttribute('role','status');el.style.cssText='position:fixed;left:50%;bottom:96px;transform:translateX(-50%);max-width:86vw;z-index:9998;background:#123d2e;color:#fff;padding:12px 16px;border-radius:14px;font:500 14px Inter,sans-serif;text-align:center;box-shadow:0 6px 18px rgba(0,0,0,.25);transition:opacity .3s';document.body.appendChild(el)}el.textContent=msg;el.style.opacity='1';clearTimeout(el._t);el._t=setTimeout(()=>{el.style.opacity='0'},2600)}
function navigateTo(v){if(!views[v])return;if(v!==S.view){try{window.RaastaVoice&&RaastaVoice.stop()}catch{}}S.view=v;render();$('#viewContainer').scrollTop=0}
document.addEventListener('click',e=>{const x=e.target.closest('[data-act],.app-navbar button,#themeToggleBtn,#headerBrand');if(!x)return;if(x.id==='headerBrand'){e.preventDefault();if(S.view==='language'||S.view==='login')return;navigateTo(complete()?'careers':(S.msgs.length?'talk':'start'));return}if(x.id==='themeToggleBtn'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';return}if(x.closest('.app-navbar')){if(x.classList.contains('locked')){navToast(navT(1));if(S.view!=='talk')navigateTo('talk');return}if(x.dataset.v==='talk'&&!S.msgs.length&&S.view!=='talk'){startChat();return}navigateTo(x.dataset.v);return}switch(x.dataset.act){case'back':goBack();break;case'lang':setLanguage(x.dataset.v);break;case'continue':S.view='start';S.pickerReturn='start';render();break;case'open-language':S.pickerReturn=S.view;S.view='language';render();break;case'start-chat':startChat();break;case'sugg':aiChatTurn(x.dataset.t||'');break;case'ai-finish':finishAI();break;case'opt':{const q=QUESTIONS[S.step];if(q)answerQuestion(q.options[+x.dataset.i]);break}case'mic':voiceListen();break;case'unsure':answerUnsure();break;case'kavya':S.profile={...KAVYA};S.msgs=[{who:'me',text:t('ownStitch')},{who:'bot',text:t('routeReady')}];S.step=QUESTIONS.length;S.view='careers';render();break;case'go':navigateTo(x.dataset.v);break;case'career':S.careerId=x.dataset.v;navigateTo('pathway');break;case'read':voiceSpeak(x.dataset.t||'',{full:1});break;case'parent':{const c=[...(S.aiRoutes||[]),...CAREERS].find(y=>y.id===S.careerId)||paths()[0];const isKavya=S.profile&&S.profile.name==='Kavya';const isMurugan=S.profile&&S.profile.name==='Murugan';const ct=L(c.title);const texts=isMurugan?{ta:`வணக்கம். முருகன் பதினாறு வயது. அவர் ஒன்பதாம் வகுப்பில் படிக்கிறார். மொபைல் போன் பழுதுபார்க்கும் திறன் உள்ளது. ${ct} ஒரு வழியாக ஆராயலாம். படிப்பு விவரங்களும் உதவித்தொகை விதிகளும் அதிகாரப்பூர்வமாக சரிபார்க்கப்பட வேண்டும்.`,en:`Hello. Murugan is 16 and in Class 9 to 10. He repairs mobile phones. ${ct} is one route to explore. Course details and scholarship rules must be checked with official sources.`,hi:`नमस्ते। मुरुगन 16 वर्ष के हैं और कक्षा 9-10 में पढ़ते हैं। वह मोबाइल फोन ठीक करते हैं। ${ct} एक संभावित रास्ता है। पाठ्यक्रम और छात्रवृत्ति आधिकारिक स्रोत से जाँचें।`,ml:`നമസ്കാരം. മുരുഗന് 16 വയസ്സ്; ഒമ്പതാം ക്ലാസ്സിൽ പഠിക്കുന്നു. മൊബൈൽ ഫോൺ നന്നാക്കുന്നു. ${ct} ഒരു സാധ്യതയുള്ള വഴിയാണ്. കോഴ്സ് വിവരങ്ങളും സ്കോളർഷിപ്പും ഔദ്യോഗിക ഉറവിടത്തിൽ പരിശോധിക്കുക.`}:isKavya?{ta:`வணக்கம். காவ்யா பதினேழு வயது. அவர் பன்னிரண்டாம் வகுப்பில் படிக்கிறார். அக்கம்பக்கத்தினருக்கு துணி தைத்துத் தருகிறார். ${ct} ஒரு வழியாக ஆராயலாம். உதவித்தொகை விதிகளும் படிப்பு விவரங்களும் அதிகாரப்பூர்வமாக சரிபார்க்கப்பட வேண்டும்.`,en:`Hello. Kavya is 17 and in Class 12. She stitches clothes for neighbours. ${ct} is one route to explore. Scholarship rules and course details must be checked with official sources.`,hi:`नमस्ते। काव्या 17 वर्ष की हैं और कक्षा 12 में पढ़ती हैं। वह पड़ोसियों के कपड़े सिलती हैं। ${ct} एक संभावित रास्ता है। छात्रवृत्ति और पाठ्यक्रम की जानकारी आधिकारिक स्रोत से जाँचें।`,ml:`നമസ്കാരം. കാവ്യയ്ക്ക് 17 വയസ്സാണ്; പ്ലസ് ടുവിൽ പഠിക്കുന്നു. അയൽവാസികൾക്കായി വസ്ത്രങ്ങൾ തുന്നുന്നു. ${ct} ഒരു സാധ്യതയുള്ള വഴിയാണ്. സ്കോളർഷിപ്പും കോഴ്സ് വിവരങ്ങളും ഔദ്യോഗിക ഉറവിടത്തിൽ പരിശോധിക്കുക.`}:{ta:`வணக்கம். உங்கள் பிள்ளை ராஸ்தாவில் தனக்கு ஏற்ற வழிகளை ஆராய்ந்தார். ${ct} ஒரு வழியாக ஆராயலாம். உதவித்தொகை விதிகளும் படிப்பு விவரங்களும் அதிகாரப்பூர்வமாக சரிபார்க்கப்பட வேண்டும்.`,en:`Hello. Your child explored career routes with Raasta. ${ct} is one route to explore. Scholarship rules and course details must be checked with official sources.`,hi:`नमस्ते। आपके बच्चे ने रास्ता पर अपने लिए करियर के रास्ते देखे। ${ct} एक संभावित रास्ता है। छात्रवृत्ति और पाठ्यक्रम की जानकारी आधिकारिक स्रोत से जाँचें।`,ml:`നമസ്കാരം. നിങ്ങളുടെ കുട്ടി റാസ്തയിൽ തനിക്കുള്ള തൊഴിൽ വഴികൾ കണ്ടു. ${ct} ഒരു സാധ്യതയുള്ള വഴിയാണ്. സ്കോളർഷിപ്പും കോഴ്സ് വിവരങ്ങളും ഔദ്യോഗിക ഉറവിടത്തിൽ പരിശോധിക്കുക.`};const box=$('#parentTranscriptText');if(isKavya&&S.lang==='ta'){if(box){box.hidden=false;box.textContent=KAVYA_NOTE_TA}try{RaastaVoice.stop&&RaastaVoice.stop()}catch{}if(window.__note&&!window.__note.paused){window.__note.pause();break}window.__note=window.__note||new Audio('assets/audio/kavya-parent-ta.mp3');window.__note.currentTime=0;window.__note.play().catch(()=>voiceSpeak(KAVYA_NOTE_TA,{full:1}));break}if(box){box.hidden=false;box.textContent=texts[S.lang]||texts.en}voiceSpeak(texts[S.lang]||texts.en,{full:1});break}case'rec':S.recommended[x.dataset.v]=true;try{localStorage.setItem('raasta_rec',JSON.stringify(S.recommended))}catch{}render();break;case'filter-fac':S.facilitatorFilter=x.dataset.v;render();break}});
window.addEventListener('online',render);window.addEventListener('offline',render);try{if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})}catch{}
try{const p=new URLSearchParams(location.search),v=p.get('v')||location.hash.slice(1);if(p.get('demo')==='kavya'||v&&v!=='start'){S.profile={...KAVYA};S.step=QUESTIONS.length;S.msgs=[{who:'bot',text:t('routeReady')}];if(views[v])S.view=v;else S.view='start'}else S.view='language'}catch{S.view='language'}render();

/* ---- Field Atlas stage (desktop showcase, voice orb, toasts) ---- */
function orbState(st){try{if(window.VoiceOrb)window.VoiceOrb.setState(st)}catch{}}
function mountOrbIfNeeded(){if(!window.VoiceOrb)return;const m=document.getElementById('orbMountEl');if(!m){window.VoiceOrb.destroy();return}if(!m.classList.contains('orb-mount-active')){window.VoiceOrb.mount(m);orbState(S.isListening?'listening':S.aiBusy?'thinking':S.isPlayingAudio?'speaking':'idle')}}
const STAGE_TXT={en:{genome:'Skill Genome',skills:n=>n+' skill'+(n===1?'':'s')+' noticed',top:'Top career route',school:'School view',students:'Students',review:'Review',referred:'Referred',steps:['Today','Learn','Next']},ta:{genome:'திறன் வரைபடம்',skills:n=>n+' திறன்கள்',top:'முதல் வழி',school:'பள்ளி பார்வை',students:'மாணவர்கள்',review:'கவனிக்க',referred:'பரிந்துரை',steps:['இன்று','கற்றல்','அடுத்து']},hi:{genome:'स्किल जीनोम',skills:n=>n+' स्किल',top:'मुख्य रास्ता',school:'स्कूल',students:'विद्यार्थी',review:'देखें',referred:'सुझाए',steps:['आज','सीखें','आगे']},ml:{genome:'സ്കിൽ ജീനോം',skills:n=>n+' കഴിവുകൾ',top:'പ്രധാന വഴി',school:'സ്കൂൾ',students:'വിദ്യാർത്ഥികൾ',review:'ശ്രദ്ധിക്കാൻ',referred:'ശുപാർശ',steps:['ഇന്ന്','പഠനം','അടുത്തത്']}};
const sT=k=>(STAGE_TXT[S.lang]||STAGE_TXT.en)[k];
function updateEditorialPanel(){const map={talk:1,language:1,start:1,login:1,careers:2,pathway:3,parent:3,profile:3,radar:3,facilitator:3};const a=map[S.view]||1;document.querySelectorAll('.ep-stage-card').forEach(c=>c.classList.toggle('active',+c.dataset.stage===a));const live=document.getElementById('epLive1'),cnt=document.getElementById('epSkillCount');const n=(S.skills||[]).length;if(live)live.style.display=n?'inline-flex':'none';if(cnt&&n)cnt.textContent=sT('skills')(n);document.body.classList.toggle('facilitator-active',S.view==='facilitator');updateBreakoutCards();if(S.view==='language'&&window.innerWidth<1100&&!document.getElementById('versionLink')){const r=document.getElementById('viewContainer');if(r){const b=document.createElement('button');b.id='versionLink';b.type='button';b.className='text-action';b.style.cssText='align-self:center;margin:6px auto 12px;opacity:.8';b.textContent='⇄ Classic version';b.addEventListener('click',()=>setAppVersion('classic'));r.appendChild(b)}}}
function updateBreakoutCards(){const slot=document.getElementById('breakoutSlot');if(!slot)return;slot.innerHTML='';if(window.innerWidth<1100)return;const sk=(S.skills||[]).slice(0,4);
 if(S.view==='talk'&&sk.length){slot.innerHTML=`<div class="breakout-genome" aria-hidden="true"><div class="genome-card-outer"><div class="genome-card-inner"><div class="gc-label">${sT('genome')}</div><div class="gc-nco">${esc(sT('skills')((S.skills||[]).length))}</div><div class="gc-chips">${sk.map(x=>`<span class="gc-chip">${esc(x)}</span>`).join('')}</div></div></div></div>`}
 else if(S.view==='careers'&&canBrowse()){const c=paths()[0];if(!c)return;const st=sT('steps');slot.innerHTML=`<div class="breakout-route" aria-hidden="true"><div class="route-card-outer"><div class="route-card-inner"><div class="rc-label">${sT('top')}</div><div class="rc-title">${esc(L(c.title))}</div><svg class="rc-spline" viewBox="0 0 200 40" aria-hidden="true"><path d="M10 30 C50 30 60 10 100 10 S160 20 190 10" fill="none" stroke="#6CBFA0" stroke-width="2.5" stroke-dasharray="3 5"/><circle cx="10" cy="30" r="4" fill="#D47234"/><circle cx="100" cy="10" r="4" fill="#114B3A"/><circle cx="190" cy="10" r="4" fill="#114B3A"/><text x="4" y="39" font-size="7" fill="#7A8C84">${esc(st[0])}</text><text x="88" y="7" font-size="7" fill="#7A8C84">${esc(st[1])}</text><text x="176" y="7" font-size="7" fill="#7A8C84">${esc(st[2])}</text></svg><div class="rc-salary">${esc(typeLabel(c.type))}</div></div></div></div>`}
 else if(S.view==='facilitator'){const rows=document.querySelectorAll('#viewContainer .student-row').length;slot.innerHTML=`<div class="breakout-school" aria-hidden="true"><div class="school-card-outer"><div class="school-card-inner"><div class="sc-label">${sT('school')}</div><div class="sc-stats"><div class="sc-stat"><span>${sT('students')}</span><strong>${rows}</strong></div><div class="sc-stat"><span>${sT('referred')}</span><strong class="referred-count">${Object.keys(S.recommended||{}).length}</strong></div></div></div></div></div>`}}
function updateNavIndicator(view){const nav=document.getElementById('appNavbar'),bg=document.getElementById('navActiveBg');if(!nav||!bg)return;const b=nav.querySelector(`button[data-v="${view}"]`);if(!b||b.offsetParent===null){bg.style.opacity='0';return}const br=b.getBoundingClientRect(),nr=nav.getBoundingClientRect();bg.style.opacity='1';bg.style.left=(br.left-nr.left+br.width/2-19)+'px'}
function showToast(msg,type='default',ms=3400){const r=document.getElementById('toastRegion');if(!r)return;const el=document.createElement('div');el.className=`raasta-toast type-${type}`;el.innerHTML=`<span class="toast-icon" aria-hidden="true"></span><span>${esc(msg)}</span>`;r.appendChild(el);const rm=()=>{el.classList.add('removing');el.addEventListener('animationend',()=>el.remove(),{once:true});setTimeout(()=>el.remove(),600)};const tm=setTimeout(rm,ms);el.addEventListener('click',()=>{clearTimeout(tm);rm()})}
document.addEventListener('click',e=>{const x=e.target.closest('[data-act="ep-nav"],[data-act="peek-nav"]');if(!x)return;const v=x.dataset.v;if(v!=='talk'&&!canBrowse()){navToast(navT(1));return}navigateTo(v)});
document.addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!==' ')return;const x=e.target.closest&&e.target.closest('[role="button"][data-act]');if(!x||x.tagName==='BUTTON')return;e.preventDefault();x.click()});
window.addEventListener('resize',()=>{updateBreakoutCards();updateNavIndicator(S.view)});
const ROUTE_ART=new Set(['agri_drone','appliance_tech','electrician','fashion_tech','food_processing','garment_supervisor','iti_sewing','mobile_tech','performing_arts','sports_coach','teacher','textile_design_digital']);
function routeArt(c){return c&&ROUTE_ART.has(c.id)?`<img class="route-art" src="assets/careers/career-${c.id.replace(/_/g,'-')}--card.svg" alt="" loading="lazy" width="72" height="72">`:''}
const DEMO_TOAST={en:{sw:(n,r)=>`Switched to ${n}`+(r?` · ${r}`:''),reset:'Demo reset',Kavya:'Kavya',Murugan:'Murugan'},ta:{sw:(n,r)=>`${n} டெமோ`+(r?` · ${r}`:''),reset:'டெமோ மீட்டமைக்கப்பட்டது',Kavya:'காவ்யா',Murugan:'முருகன்'},hi:{sw:(n,r)=>`${n} का डेमो`+(r?` · ${r}`:''),reset:'डेमो रीसेट हुआ',Kavya:'काव्या',Murugan:'मुरुगन'},ml:{sw:(n,r)=>`${n} ഡെമോ`+(r?` · ${r}`:''),reset:'ഡെമോ പുനഃസജ്ജമാക്കി',Kavya:'കാവ്യ',Murugan:'മുരുഗൻ'}};
function demoToast(name){const d=DEMO_TOAST[S.lang]||DEMO_TOAST.en;if(!name){showToast(d.reset,'info');return}const c=paths()[0];showToast(d.sw(d[name]||name,c?L(c.title):''),'success')}
window.demoToast=demoToast;
// Opening Talk without a started conversation (after a demo button, Reset or a reload) goes to the AI voice chat, not the tap questionnaire.
function ensureTalk(){if(S.chatMode)return;S.skills=S.skills||[];S.convo=S.convo||[];S.msgs=S.msgs||[];S.asked=S.asked||[];S.retried=S.retried||[];if(!navigator.onLine){S.chatMode='rules';S.step=Math.max(0,QUESTIONS.findIndex(q=>S.profile[q.key]===undefined));if(!S.msgs.length&&QUESTIONS[S.step])S.msgs.push({who:'bot',text:L(QUESTIONS[S.step])});return}S.chatMode='ai';if(!S.convo.length){const open=L(QUESTIONS[0]);S.msgs=[{who:'bot',text:open}];S.convo=[{role:'assistant',content:open}]}}
// Demo deck: a real live voice conversation with a fresh student (replaces the old simulation).
function startLiveDemo(){startChat();setTimeout(()=>voiceListen(),50)}
window.startLiveDemo=startLiveDemo;
// App version switch (desktop panel): the classic app runs inside the same phone frame, on the Field Atlas background.
function setAppVersion(v){const on=v==='classic';const scr=document.querySelector('.device-screen')||document.getElementById('deviceMock');let f=document.getElementById('classicFrame');if(on&&!f&&scr){f=document.createElement('iframe');f.id='classicFrame';f.title='Raasta classic';f.src='classic/';f.allow='microphone; autoplay';scr.appendChild(f)}if(!on&&f)f.remove();document.body.classList.toggle('classic-on',on);document.querySelectorAll('[data-act="app-version"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.v===(on?'classic':'atlas'))));try{localStorage.setItem('raasta_app_version',on?'classic':'atlas')}catch{}}
document.addEventListener('click',e=>{const x=e.target.closest('[data-act="app-version"]');if(x){setAppVersion(x.dataset.v);return}if(document.body.classList.contains('classic-on')&&e.target.closest('.editorial-panel [data-act],.peek-phone'))setAppVersion('atlas')},true);
(()=>{let v=null;try{v=new URLSearchParams(location.search).has('classic')?'classic':localStorage.getItem('raasta_app_version')}catch{}if(v==='classic')setAppVersion('classic')})();
