const PT=()=>PARENT_TXT[S.lang]||PARENT_TXT.en;
function parentData(){const p=PT();const me=window.RaastaAuth&&RaastaAuth.me&&RaastaAuth.me();const name=(me&&me.role!=='teacher'&&me.name&&me.name!=='Guest'?me.name:'')||S.profile.name||p.child;
 const ints=(S.profile.interests||[]).map(v=>{const o=QUESTIONS[0].options.find(x=>x.v===v);return o?L(o):v});const skills=[...new Set([...(S.skills||[]),...ints])];
 const c=[...(S.aiRoutes||[]),...CAREERS].find(x=>x.id===S.careerId)||paths()[0]||null;
 const steps=c&&c.path?c.path.slice(0,3).map(q=>(typeof STEP_I18N!=='undefined'&&STEP_I18N[q[0]]&&STEP_I18N[q[0]][S.lang])||q[0]):[];
 const items=eligibility(S.profile).filter(o=>o.status!=='not_eligible').slice(0,4);return {p,name,skills,c,steps,items}}
function parentView(){const {p,name,skills,c,steps,items}=parentData();const say=x=>`<button class="parent-listen" data-act="read-full" data-t="${esc(x)}">${p.listen}</button>`;
 const skillTxt=skills.join(', ');const routeTxt=c?`${L(c.title)}. ${c.why_i18n?.[S.lang]??c.why??''}`:'';const schemeTxt=items.map(o=>localizedOpp(o.opportunity_id,'name_i18n',o.name)).join(', ');
 return `<div class="parent-view">${topbar(p.title,p.eyebrow,esc(p.intro(name)))}
 <section class="parent-card">${skills.length?say(p.good(name)+': '+skillTxt):''}<div class="eyebrow">01</div><h2>${esc(p.good(name))}</h2>${skills.length?`<div class="parent-chips">${skills.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:`<p>${p.noSkills}</p>`}</section>
 ${c?`<section class="parent-card">${say(p.route+': '+routeTxt+' '+p.notPromise)}<div class="eyebrow">02</div><h2>${esc(p.route)}</h2>${routeArt(c)}<p><strong>${esc(L(c.title))}</strong></p><p>${esc(c.why_i18n?.[S.lang]??c.why??'')}</p>${steps.length?`<p class="note" style="margin-top:10px"><strong>${p.steps}</strong></p><ol>${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}<p class="note">${p.notPromise}</p><button class="text-action" data-act="career" data-v="${esc(c.id)}">${t('myPath')} →</button></section>`:''}
 <section class="parent-card">${say(p.support+': '+(schemeTxt||p.noSupport))}<div class="eyebrow">03</div><h2>${esc(p.support)}</h2>${items.length?items.map(o=>`<div class="parent-scheme"><strong>${esc(localizedOpp(o.opportunity_id,'name_i18n',o.name))}</strong><span>${esc(localizedOpp(o.opportunity_id,'benefit_i18n',o.benefit))}</span>${eligSummary(o)}<a class="source-action" href="${esc(o.source_url)}" target="_blank" rel="noopener">${t('official')} ↗</a></div>`).join(''):`<p>${p.noSupport}</p>`}<p class="note">${p.supportNote}</p></section>
 <section class="parent-card">${say(p.papers+': '+p.papersList(S.profile.category).join(', '))}<div class="eyebrow">04</div><h2>${esc(p.papers)}</h2><ul>${p.papersList(S.profile.category).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="note">${p.papersNote}</p></section>
 <section class="parent-card">${say(p.week+': '+p.weekList(name).join(' '))}<div class="eyebrow">05</div><h2>${esc(p.week)}</h2><ol>${p.weekList(name).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>
 <div class="parent-actions">${c?`<button class="primary-action" data-act="parent">${p.voice} →</button><div id="parentTranscriptText" class="transcript" hidden></div>`:''}<a class="secondary-action" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(parentShare())}">${p.share}</a></div></div>`}
function parentShare(){const {p,name,skills,c,steps,items}=parentData();return [p.shareHead(name),'',skills.length?`${p.good(name)}: ${skills.join(', ')}`:'',c?`${p.route}: ${L(c.title)}`:'',steps.length?`${p.steps}: ${steps.join('; ')}`:'',items.length?`${p.support}: ${items.map(o=>localizedOpp(o.opportunity_id,'name_i18n',o.name)).join(', ')}`:'',`${p.papers}: ${p.papersList(S.profile.category).join(', ')}`,'',p.supportNote,'https://raasta-poc.vercel.app'].filter((x,i,a)=>x!==''||a[i-1]!=='').join('\n')}
document.addEventListener('click',e=>{const x=e.target.closest('[data-act="read-full"]');if(!x)return;voiceSpeak(x.dataset.t||'',{full:true})});
/* ---- App version switch on phones: floating pill (the desktop panel is hidden there) ---- */
function versionFab(){let b=document.getElementById('versionFab');if(!b){b=document.createElement('button');b.id='versionFab';b.type='button';b.addEventListener('click',()=>setAppVersion(document.body.classList.contains('classic-on')?'atlas':'classic'));document.body.appendChild(b)}const on=document.body.classList.contains('classic-on');b.textContent=on?'⇄ Field Atlas':'⇄ Classic';b.setAttribute('aria-label',on?'Switch to Field Atlas version':'Switch to Classic version');b.hidden=!on}
new MutationObserver(versionFab).observe(document.body,{attributes:true,attributeFilter:['class']});versionFab();
